import { useState } from 'react';
import { KeyboardSensor, PointerSensor, useSensor, useSensors } from '@dnd-kit/core';
import CareerListHeader from './CareerListHeader';
import KanbanBoard from './KanbanBoard';
import ApplicantDetailsDialog from './ApplicantDetailsDialog';
import TypeChangeDialog from './TypeChangeDialog';
import InterviewEvaluation from './InterviewEvaluation';
import { useSalesList } from './useSalesList';

export default function CarerListComponent() {
    const [searchQuery, setSearchQuery] = useState('');

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 8,
            },
        }),
        useSensor(KeyboardSensor),
    );

    const {
        salesStages,
        isLoading,
        activeId,
        selectedApplicantId,
        applicantDetails,
        isTypeChangeDialogOpen,
        pendingTypeChange,
        isSubmittingTypeChange,
        handleDragStart,
        handleDragEnd,
        handleCardClick,
        handleCloseDialog,
        handleTypeChangeSubmit,
        handleCloseTypeChangeDialog,
        openEvaluationDialog,
        evaluationInterview,
        setopenEvaluationDialog,
    } = useSalesList(searchQuery);

    if (isLoading) {
        return (
            <div className="w-full bg-gray-100/45 p-6 rounded-lg mt-6">
                <div className="flex items-center justify-center h-64">
                    <p className="text-gray-600 font-cairo">جاري التحميل...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="w-full bg-gray-100/45 p-6 rounded-lg mt-6">
            <CareerListHeader searchQuery={searchQuery} onSearchChange={setSearchQuery} />
            <KanbanBoard
                salesStages={salesStages}
                activeId={activeId}
                sensors={sensors}
                onDragStart={handleDragStart}
                onDragEnd={handleDragEnd}
                onCardClick={handleCardClick}
            />
            <ApplicantDetailsDialog
                isOpen={selectedApplicantId !== null}
                applicant={applicantDetails}
                onClose={handleCloseDialog}
            />


            <TypeChangeDialog
                isOpen={isTypeChangeDialogOpen}
                targetStage={pendingTypeChange?.targetStage ?? null}
                onClose={handleCloseTypeChangeDialog}
                onSubmit={handleTypeChangeSubmit}
                isLoading={isSubmittingTypeChange}
                formResetKey={
                    pendingTypeChange
                        ? `${pendingTypeChange.applicantId}-${pendingTypeChange.targetStage.id}`
                        : 'closed'
                }
                applicantName={pendingTypeChange?.applicantName}
                previousStageName={pendingTypeChange?.previousStageName}
                applicantJobTitle={pendingTypeChange?.applicantJobTitle}
                applicantWorkType={pendingTypeChange?.applicantWorkType}
                applicantExperienceYears={pendingTypeChange?.applicantExperienceYears}
            />

            <InterviewEvaluation
                interview={evaluationInterview}
                openEvaluationDialog={openEvaluationDialog}
                setopenEvaluationDialog={setopenEvaluationDialog}
            />
        </div>
    );
}
