import { useState, useEffect, useCallback } from 'react';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';
import { DragStartEvent, DragEndEvent } from '@dnd-kit/core';
import { PipelineStageFormSubmit, SalesStage } from '../../types/configs.types';
import { salesStagesConfig } from './constants';
import {
    applicantToEvaluationInterview,
    isRichTextNotesEmpty,
    normalizePipelineStage,
    transformApplicantToDeal,
} from './utils';
import { Applicant } from '../../types/app.types';
import { Interview } from '../../types/interview.types';

export function useSalesList(searchQuery = '') {
    const [salesStages, setSalesStages] = useState<SalesStage[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeId, setActiveId] = useState<string | null>(null);
    const [applicantsMap, setApplicantsMap] = useState<Map<number, Applicant>>(new Map());
    const [selectedApplicantId, setSelectedApplicantId] = useState<number | null>(null);
    const [applicantDetails, setApplicantDetails] = useState<Applicant | null>(null);
    const [isTypeChangeDialogOpen, setIsTypeChangeDialogOpen] = useState(false);
    const [pendingTypeChange, setPendingTypeChange] = useState<{
        applicantId: number;
        targetStage: SalesStage;
        dealId: string;
        applicantName: string;
        previousStageName: string;
        applicantJobTitle?: string;
        applicantWorkType?: string;
        applicantExperienceYears?: number | null;
    } | null>(null);
    const [isSubmittingTypeChange, setIsSubmittingTypeChange] = useState(false);
    const [allSalesStages, setAllSalesStages] = useState<SalesStage[]>([]);
    const [openEvaluationDialog, setOpenEvaluationDialog] = useState(false);
    const [evaluationInterview, setEvaluationInterview] = useState<Interview | null>(null);

    const fetchApplicants = useCallback(async () => {
        setIsLoading(true);

        const applyStagesFromApplicants = (allApplicants: Applicant[]) => {
            const mapData = new Map<number, Applicant>();
            allApplicants.forEach((applicant) => {
                mapData.set(applicant.id, applicant);
            });
            setApplicantsMap(mapData);

            const applicantsByType = allApplicants.reduce(
                (acc, applicant) => {
                    const type = normalizePipelineStage(applicant.pipeline_stage);
                    if (!acc[type]) {
                        acc[type] = [];
                    }
                    acc[type].push(applicant);
                    return acc;
                },
                {} as Record<string, Applicant[]>,
            );

            const stages: SalesStage[] = salesStagesConfig.map((stageConfig) => {
                const applicantsOfType = applicantsByType[stageConfig.type] || [];
                const deals = applicantsOfType.map(transformApplicantToDeal);

                return {
                    ...stageConfig,
                    count: applicantsOfType.length,
                    deals,
                };
            });

            setAllSalesStages(stages);
        };

        try {
            let allApplicants: Applicant[] = [];
            let currentPage = 1;
            let hasMorePages = true;

            while (hasMorePages) {
                const response = await apiGet({
                    endpoint: endpoints.career.list,
                    queryParams: {
                        page: currentPage,
                        pageSize: 100,
                    },
                });

                const pageData: Applicant[] = response.data?.data?.data || [];
                const pagination = response.data?.data?.pagination;

                allApplicants = [...allApplicants, ...pageData];

                if (pagination) {
                    const totalPages = Math.ceil(pagination.total / (pagination.per_page || 100));
                    hasMorePages = currentPage < totalPages;
                } else {
                    hasMorePages = false;
                }

                currentPage++;

                if (currentPage > 100) {
                    break;
                }
            }

            applyStagesFromApplicants(allApplicants);
        } catch {
            applyStagesFromApplicants([]);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        if (!searchQuery.trim()) {
            setSalesStages(allSalesStages);
            return;
        }

        const query = searchQuery.toLowerCase().trim();
        const filteredStages = allSalesStages.map((stage) => {
            const filteredDeals = stage.deals.filter((deal) => {
                const name = deal.name?.toLowerCase() || '';
                const jobTitle = ((deal as { jobTitle?: string }).jobTitle || '').toLowerCase();
                return name.includes(query) || jobTitle.includes(query);
            });

            return {
                ...stage,
                deals: filteredDeals,
                count: filteredDeals.length,
            };
        });

        setSalesStages(filteredStages);
    }, [searchQuery, allSalesStages]);

    useEffect(() => {
        fetchApplicants();
    }, [fetchApplicants]);

    const handleDragStart = (event: DragStartEvent) => {
        setActiveId(event.active.id as string);
    };

    const handleCardClick = (dealId: string) => {
        const id = parseInt(dealId, 10);
        if (Number.isNaN(id)) return;

        if (selectedApplicantId === id && applicantDetails) {
            return;
        }

        setSelectedApplicantId(id);
        setApplicantDetails(applicantsMap.get(id) ?? null);
    };

    const handleCloseDialog = () => {
        setSelectedApplicantId(null);
        setApplicantDetails(null);
    };

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        setActiveId(null);

        if (!over) return;

        const dealId = active.id as string;
        const targetStageId = over.id as string;

        const currentStage = salesStages.find((stage) => stage.deals.some((deal) => deal.id === dealId));

        if (!currentStage) return;

        if (currentStage.id === targetStageId) return;

        const targetStage = salesStages.find((stage) => stage.id === targetStageId);
        if (!targetStage) return;

        const applicantId = parseInt(dealId, 10);
        const applicant = applicantsMap.get(applicantId);

        if (!applicant) return;

        const isTechnicalToEmployee = currentStage.type === 'contact' && targetStage.type === 'completed';
        if (isTechnicalToEmployee) {
            setEvaluationInterview(applicantToEvaluationInterview(applicant));
            setOpenEvaluationDialog(true);
            return;
        }

        setPendingTypeChange({
            applicantId,
            targetStage,
            dealId,
            applicantName: applicant.name,
            previousStageName: currentStage.name,
            applicantJobTitle: applicant.job?.title ?? applicant.job?.name ?? applicant.job_title ?? undefined,
            applicantWorkType: applicant.work_type ?? undefined,
            applicantExperienceYears:
                typeof applicant.experience_years === 'number' ? applicant.experience_years : null,
        });
        setIsTypeChangeDialogOpen(true);
    };

    const handleTypeChangeSubmit = async ({ notes, pipeline_started_at }: PipelineStageFormSubmit) => {
        if (!pendingTypeChange) return;

        setIsSubmittingTypeChange(true);

        try {
            const body: { pipeline_stage: string; notes?: string; pipeline_started_at?: string } = {
                pipeline_stage: pendingTypeChange.targetStage.type,
            };
            if (!isRichTextNotesEmpty(notes)) {
                body.notes = notes;
            }
            if (pipeline_started_at) {
                body.pipeline_started_at = pipeline_started_at;
            }

            await apiPost({
                endpoint: `${endpoints.applicant.update}${pendingTypeChange.applicantId}`,
                body,
            });

            toast.success('تم تحديث مرحلة المرشح بنجاح');

            setIsTypeChangeDialogOpen(false);
            setPendingTypeChange(null);

            setTimeout(() => {
                fetchApplicants();
            }, 300);
        } catch (error: unknown) {
            let errorMessage = 'حدث خطأ أثناء تحديث المرحلة. يرجى المحاولة مرة أخرى.';
            if (error && typeof error === 'object' && 'response' in error) {
                const ax = error as { response?: { data?: { msg?: string; message?: string } } };
                errorMessage = ax.response?.data?.msg || ax.response?.data?.message || errorMessage;
            } else if (error && typeof error === 'object' && 'request' in error) {
                errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
            }
            toast.error(errorMessage);
        } finally {
            setIsSubmittingTypeChange(false);
        }
    };

    const handleCloseTypeChangeDialog = () => {
        setIsTypeChangeDialogOpen(false);
        setPendingTypeChange(null);
    };

    const setopenEvaluationDialog = (open: boolean) => {
        setOpenEvaluationDialog(open);
        if (!open) setEvaluationInterview(null);
    };

    return {
        salesStages,
        isLoading,
        activeId,
        selectedApplicantId,
        applicantDetails,
        isLoadingDetails: false,
        isTypeChangeDialogOpen,
        pendingTypeChange,
        isSubmittingTypeChange,
        handleDragStart,
        handleDragEnd,
        handleCardClick,
        handleCloseDialog,
        handleTypeChangeSubmit,
        handleCloseTypeChangeDialog,
        setIsTypeChangeDialogOpen,
        setPendingTypeChange,
        openEvaluationDialog,
        evaluationInterview,
        setopenEvaluationDialog,
    };
}
