import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import FileDownloadIcon from '@/components/icons/file/FileDownloadIcon';
import SearchIcon from '@/components/icons/Search';

interface CareerListHeaderProps {
    searchQuery: string;
    onSearchChange: (value: string) => void;
}

export default function CareerListHeader({ searchQuery, onSearchChange }: CareerListHeaderProps) {
    return (
        <div className="flex items-center justify-between mb-6 flex-wrap gap-4">
            <h2 className="text-2xl font-semibold text-primery-blue-700 font-cairo">
                مسار التوظيف
            </h2>
            <div className="flex items-center gap-4 flex-wrap">
                <div className="flex flex-row items-center w-[287px] border border-white-blue-300 bg-white-blue-50 h-[36px] p-2 rounded-[6px]">
                    <Input
                        placeholder="البحث"
                        value={searchQuery}
                        onChange={(event) => onSearchChange(event.target.value)}
                        className="text-white-blue-800 p-0 tracking-normal text-xs lg:text-sm lg:leading-[16.8px] border-none outline-none focus-visible:ring-0 placeholder:text-white-blue-800"
                    />
                    <button className="bg-transparent border-none">
                        <SearchIcon className="text-white-blue-800" />
                    </button>
                </div>
                <Button
                    variant="outline"
                    className="bg-gray-200 text-gray-700 hover:bg-gray-300 rounded-lg px-4 py-2 flex items-center gap-2 border-gray-300 font-cairo"
                >
                    <FileDownloadIcon width="16" height="16" />
                    <span>تصدير</span>
                </Button>
            </div>
        </div>
    );
}

