import StatisticsCards from '@/components/cards/StatisticsCards';
import CareerList from '../components/careerList/CareerList';
import { Card } from '@/types/statistics';
import GroupIcon from '@/components/icons/user/GroupIcon';
import UserRemoveIcon from '@/components/icons/UserRemoveIcon';
import { useEffect, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { careerStats } from '../types/career.types';
import TwoUsersIcon from '@/components/icons/user/TwoUsersIcon';

const CareerPath = () => {
    const [stats, setStats] = useState<careerStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.job.dashboard });
                setStats(res.data.data);
            } catch {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    const cards: Card[] = [
        { text: 'إجمالي المتقدمين', num: stats?.total_applicants, percent: 0, icon: <UserRemoveIcon /> },
        { text: 'اجمالي المقابلات', num: stats?.total_interviews, percent: 0, icon: <GroupIcon /> },
        { text: 'الفرص', num: stats?.total_jobs, percent: 0, icon: <TwoUsersIcon /> },
    ];

    return (
        <div className="mt-6 w-full">
            <StatisticsCards cards={cards} className="mt-6" />
            <CareerList />
        </div>
    );
};

export default CareerPath;
