/** عنوان نافذة جدولة المقابلة/المرحلة حسب `type` للعمود الهدف في الكنبان */
export const TYPE_CHANGE_DIALOG_TITLE_BY_STAGE_TYPE: Partial<Record<string, string>> = {
    qualified: 'جدولة مقابلة ادارة الموارد البشرية',
    contact: 'جدول المقابلة تقنية',
};

export function getTypeChangeDialogTitle(stageType: string, stageDisplayName: string): string {
    const specific = TYPE_CHANGE_DIALOG_TITLE_BY_STAGE_TYPE[stageType];
    if (specific) return specific;
    return `جدولة ${stageDisplayName}`;
}
