import React from 'react';
import { Card } from '@/components/ui/card';
import { cn } from '@/lib/utils';
import { useDraggable } from '@dnd-kit/core';
import { Deal } from '../../types/configs.types';

interface DraggableCardProps {
    deal: Deal;
    activeId: string | null;
    onCardClick: (dealId: string) => void;
}

export default function DraggableCard({ deal, activeId, onCardClick }: DraggableCardProps) {
    const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
        id: deal.id,
    });

    const style = transform
        ? {
              transform: `translate3d(${transform.x}px, ${transform.y}px, 0)`,
          }
        : undefined;

    const handleClick = (e: React.MouseEvent) => {
        // Prevent opening dialog when dragging
        if (!isDragging && activeId !== deal.id) {
            e.stopPropagation();
            onCardClick(deal.id);
        }
    };

    const candidateName = deal.name || '—';
    const jobTitle = ((deal as { jobTitle?: string }).jobTitle ?? '').trim() || '—';
    const experienceText = ((deal as { experienceLabel?: string }).experienceLabel ?? '').trim() || '—';
    const tags = ((deal as { tags?: string[] }).tags ?? []).slice(0, 6);
    const pipelineStageText = ((deal as { pipeline_stage?: string }).pipeline_stage ?? '').trim() || '—';
// console.log('pipelineStageText', deal);
    return (
        <Card
            ref={setNodeRef}
            style={style}
            {...listeners}
            {...attributes}
            onClick={handleClick}
            className={cn(
                'rounded-2xl border border-[#E5E7EB] bg-white p-3.5 shadow-sm transition-shadow hover:shadow-md cursor-grab active:cursor-grabbing',
                (isDragging || activeId === deal.id) && 'opacity-50',
                !isDragging && activeId !== deal.id && 'cursor-pointer'
            )}
        >
            <div className="space-y-3" dir="rtl">
                <div className="flex items-start justify-between">
                    <h4 className="text-[22px] leading-[32px] font-semibold text-[#111827]">{candidateName}</h4>
                    <span className="rounded-md bg-[#FFF4E5] px-2.5 py-1 text-[11px] leading-4 text-[#B76E00]">
                        {pipelineStageText}
                    </span>
                </div>

                <div className="text-right">
                    <p className="text-[15px] text-[#4B5563]">{jobTitle}</p>
                    <p className="text-[15px] text-[#4B5563]">{experienceText}</p>
                </div>

                <div className="flex flex-wrap justify-start gap-2">
                    {tags.map((tag, index) => (
                        <span
                            key={`${deal.id}-${index}-${tag}`}
                            className="rounded-md bg-[#EEF2FF] px-2 py-0.5 text-[15px] leading-[21px] text-[#4361EE]"
                        >
                            {tag}
                        </span>
                    ))}
                </div>
            </div>
        </Card>
    );
}


