import React from 'react';
import { useDroppable } from '@dnd-kit/core';
import { cn } from '@/lib/utils';
import { SalesStage } from '../../types/configs.types';

interface DroppableColumnProps {
    stage: SalesStage;
    children: React.ReactNode;
    activeId: string | null;
}

export default function DroppableColumn({ stage, children, activeId }: DroppableColumnProps) {
    const { setNodeRef, isOver } = useDroppable({
        id: stage.id,
    });

    return (
        <div
            ref={setNodeRef}
            className={cn(
                'flex-shrink-0 w-[300px] min-h-[400px] rounded-lg p-2 transition-colors',
                isOver && 'bg-blue-50 border-2 border-blue-300 border-dashed'
            )}
        >
            {children}
        </div>
    );
}

