import { Formik } from 'formik';
import { Calendar, ChevronDown } from 'lucide-react';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { TypeChangeDialogProps } from '../../types/configs.types';
import { formatDateAndTimeForApi } from './utils';
import { cn } from '@/lib/utils';
import type { ReactNode } from 'react';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import { getTypeChangeDialogTitle } from './constants';

function FieldShell({ label, children }: { label: string; children: ReactNode }) {
    return (
        <div className="space-y-1.5 text-right">
            <span className="block text-sm font-medium text-[#374151]">{label}</span>
            {children}
        </div>
    );
}

export default function TypeChangeDialog({
    isOpen,
    targetStage,
    onClose,
    onSubmit,
    isLoading = false,
    formResetKey = 'default',
    applicantName,
    applicantJobTitle,
    applicantWorkType,
    applicantExperienceYears,
}: TypeChangeDialogProps) {
    const jobDisplay = applicantJobTitle?.trim() || '—';
    const workDisplay = applicantWorkType?.trim() || '—';
    const experienceDisplay =
        typeof applicantExperienceYears === 'number'
            ? `${applicantExperienceYears.toLocaleString('ar-EG')} سنوات`
            : '—';

    const dialogTitle = targetStage
        ? getTypeChangeDialogTitle(targetStage.type, targetStage.name)
        : '';

    return (
        <Dialog
            open={isOpen}
            onOpenChange={(open) => {
                if (!open) onClose();
            }}
        >
            {targetStage ? (
                <DialogContent
                    dir="rtl"
                    showCloseButton={false}
                    className="max-w-lg gap-0 overflow-hidden border-[#E8E7EA] p-0 sm:max-w-xl"
                >
                    <div className="space-y-3 border-b border-[#E5E7EB] px-5 pb-4 pt-5 text-end sm:px-6">
                        <h2 className="flex items-center gap-2 text-lg font-semibold text-[#145DA0]">
                            <PlusIcon className="h-5 w-5 stroke-[2.5] text-white" aria-hidden />
                            {dialogTitle}
                        </h2>
                    </div>

                    <Formik
                        key={String(formResetKey)}
                        initialValues={{
                            interviewDate: '',
                            interviewTime: '',
                        }}
                        onSubmit={async (values) => {
                            const pipeline_started_at = formatDateAndTimeForApi(
                                values.interviewDate,
                                values.interviewTime,
                            );
                            await onSubmit({
                                notes: '',
                                ...(pipeline_started_at ? { pipeline_started_at } : {}),
                            });
                        }}
                    >
                        {({ handleSubmit, isSubmitting, values, setFieldValue }) => (
                            <form onSubmit={handleSubmit} className="px-5 py-5 sm:px-6">
                                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                                    <FieldShell label="اسم المتقدم">
                                        <div className="relative">
                                            <input
                                                disabled
                                                readOnly
                                                value={applicantName ?? ''}
                                                placeholder="اختر الاسم"
                                                className={cn('disabledInputClass', 'pe-10')}
                                            />
                                            <ChevronDown
                                                className="pointer-events-none absolute top-1/2 h-4 w-4 -translate-y-1/2 text-[#6B7280] end-3"
                                                aria-hidden
                                            />
                                        </div>
                                    </FieldShell>

                                    <FieldShell label="الوظيفة">
                                        <input disabled readOnly value={jobDisplay} className="disabledInputClass" />
                                    </FieldShell>

                                    <FieldShell label="سنوات الخبرة">
                                        <input
                                            disabled
                                            readOnly
                                            value={experienceDisplay}
                                            className="disabledInputClass"
                                        />
                                    </FieldShell>

                                    <FieldShell label="نوع العمل">
                                        <input disabled readOnly value={workDisplay} className="disabledInputClass" />
                                    </FieldShell>

                                    <FieldShell label="التاريخ">
                                        <div className="relative">
                                            <input
                                                type="date"
                                                name="interviewDate"
                                                value={values.interviewDate}
                                                onChange={(e) => setFieldValue('interviewDate', e.target.value)}
                                                className="editableInputClass"
                                            />
                                            <Calendar
                                                className="pointer-events-none absolute top-1/2 h-4 w-4 -translate-y-1/2 text-[#6B7280] end-3"
                                                aria-hidden
                                            />
                                        </div>
                                    </FieldShell>

                                    <FieldShell label="الوقت">
                                        <div className="relative">
                                            <input
                                                type="time"
                                                name="interviewTime"
                                                value={values.interviewTime}
                                                onChange={(e) => setFieldValue('interviewTime', e.target.value)}
                                                className="editableInputClass"
                                            />
                                            <ChevronDown
                                                className="pointer-events-none absolute top-1/2 h-4 w-4 -translate-y-1/2 text-[#6B7280] end-3"
                                                aria-hidden
                                            />
                                        </div>
                                    </FieldShell>
                                </div>

                                <div className="mt-6 flex flex-row-reverse w-full items-center justify-start gap-3 border-t border-[#E5E7EB] pt-4">
                                    <div className="relative">
                                        <span
                                            className="pointer-events-none absolute -top-1 end-0 z-10 h-2 w-2 rounded-full bg-red-500 ring-2 ring-white"
                                            aria-hidden
                                        />
                                        <SecondaryButton
                                            type="button"
                                            onClick={onClose}
                                            disabled={isLoading || isSubmitting}
                                            className="min-w-[100px] border border-[#D1D5DB] bg-white font-medium text-[#6B7280] hover:bg-[#F9FAFB]"
                                        >
                                            إلغاء
                                        </SecondaryButton>
                                    </div>
                                    <PrimaryButton
                                        type="submit"
                                        disabled={isLoading || isSubmitting}
                                        className="min-w-[120px] rounded-lg bg-primery-blue-800 px-6 py-2.5 font-semibold hover:bg-primery-blue-700"
                                    >
                                        {isLoading || isSubmitting ? (
                                            <span className="flex items-center justify-center gap-2">
                                                <span className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
                                                جاري الحفظ…
                                            </span>
                                        ) : (
                                            'اضافة'
                                        )}
                                    </PrimaryButton>
                                </div>
                            </form>
                        )}
                    </Formik>
                </DialogContent>
            ) : null}
        </Dialog>
    );
}
