import { useMemo, type ReactNode } from 'react';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import { Applicant } from '../../types/app.types';
import { formatDateTimeArEg, formatDateToArabic } from './utils';
import MainHeading from '@/components/heading/MainHeading';
import CloseIcon from '@/components/icons/CloseIcon';

interface ApplicantDetailsDialogProps {
    isOpen: boolean;
    applicant: Applicant | null;
    onClose: () => void;
}

function parseSkillItems(applicant: Applicant): string[] {
    const split = (value: string) =>
        value
            .split(/[\r\n,]+|\s+/)
            .map((s) => s.trim())
            .filter(Boolean);

    if (Array.isArray(applicant.skills)) return applicant.skills.filter(Boolean) as string[];
    if (typeof applicant.skills === 'string' && applicant.skills.trim()) return split(applicant.skills);
    if (applicant.skills_text?.trim()) return split(applicant.skills_text);
    return [];
}


function FieldBlock({
    label,
    children,
    className,
}: {
    label: string;
    children: ReactNode;
    className?: string;
}) {
    return (
        <div
            className={cn(
                'rounded-xl border border-[#E8E7EA] bg-gradient-to-b from-white to-[#FAFBFC] px-3.5 py-3 shadow-[0_1px_0_0_rgba(15,23,42,0.04)]',
                className,
            )}
        >
            <p className="text-xs font-medium text-[#625E74]">{label}</p>
            <div className="mt-1 text-sm font-semibold leading-relaxed text-[#111827]">{children}</div>
        </div>
    );
}

export default function ApplicantDetailsDialog({ isOpen, applicant, onClose }: ApplicantDetailsDialogProps) {
    const skillItems = useMemo(() => (applicant ? parseSkillItems(applicant) : []), [applicant]);

    const jobTitle = applicant?.job?.title ?? applicant?.job?.name ?? applicant?.job_title;

    const hasMetaFields = Boolean(
        applicant &&
        (applicant.level ||
            applicant.work_type ||
            applicant.department?.name ||
            typeof applicant.experience_years === 'number' ||
            applicant.status),
    );
    const handleClose = () => {
        onClose();
    };

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent
                dir="rtl"
                className="max-h-[90vh] max-w-lg gap-0 overflow-hidden border-[#E8E7EA] p-0 sm:max-w-xl"
            >
                <div className="max-h-[90vh] overflow-y-auto">
                    <div className="pb-4 pt-5 text-white sm:px-6 w-full flex flex-row items-center justify-between gap-2">
                        <MainHeading text="تفاصيل المرشح" className='w-full text-start' />
                        <button onClick={handleClose} className='mb-4'>
                            <CloseIcon className='text-blue-900' />
                        </button>
                    </div>

                    {applicant ? (
                        <>
                            <div className="border-b border-[#E8E7EA] bg-primery-blue-50/60 px-5 py-4 sm:px-6">
                                <div className="flex flex-row-reverse items-center gap-4 text-right">
                                    <div
                                        className=""
                                        aria-hidden
                                    >
                                        {applicant.pipeline_stage ? (
                                            <span className="mt-2 inline-flex max-w-full items-center rounded-full bg-white px-2.5 py-0.5 text-xs font-medium text-primery-blue-800 ring-1 ring-primery-blue-200/80">
                                                {applicant.pipeline_stage}
                                            </span>
                                        ) : null}
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <h2 className="truncate text-lg font-bold text-primery-blue-900">
                                            {applicant.name}
                                        </h2>
                                        {jobTitle ? (
                                            <p className="mt-0.5 truncate text-sm text-[#625E74]">{jobTitle}</p>
                                        ) : (
                                            <p className="mt-0.5 text-sm text-[#9CA3AF]">لم يُحدد المنصب</p>
                                        )}

                                    </div>
                                </div>
                            </div>

                            <div className="space-y-4 px-5 py-5 sm:px-6">
                                {hasMetaFields ? (
                                    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                                        {applicant.level ? (
                                            <FieldBlock label="المستوى">{applicant.level}</FieldBlock>
                                        ) : null}
                                        {applicant.work_type ? (
                                            <FieldBlock label="نوع العمل">{applicant.work_type}</FieldBlock>
                                        ) : null}
                                        {applicant.department?.name ? (
                                            <FieldBlock label="القسم">{applicant.department.name}</FieldBlock>
                                        ) : null}
                                        {typeof applicant.experience_years === 'number' ? (
                                            <FieldBlock label="سنوات الخبرة">
                                                {applicant.experience_years.toLocaleString('ar-EG')}
                                            </FieldBlock>
                                        ) : null}
                                        {applicant.status ? (
                                            <FieldBlock label="الحالة">{applicant.status}</FieldBlock>
                                        ) : null}
                                    </div>
                                ) : null}

                                {(applicant.pipeline_started_at || applicant.created_at) && (
                                    <>
                                        <Separator className="bg-[#E8E7EA]" />
                                        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                                            {applicant.pipeline_started_at ? (
                                                <FieldBlock label="تاريخ بدء المرحلة">
                                                    {formatDateTimeArEg(applicant.pipeline_started_at)}
                                                </FieldBlock>
                                            ) : null}
                                            {applicant.created_at ? (
                                                <FieldBlock label="تاريخ التقديم">
                                                    {formatDateToArabic(applicant.created_at)}
                                                </FieldBlock>
                                            ) : null}
                                        </div>
                                    </>
                                )}

                                {skillItems.length > 0 ? (
                                    <>
                                        <Separator className="bg-[#E8E7EA]" />
                                        <div>
                                            <p className="mb-2 text-xs font-medium text-[#625E74]">المهارات</p>
                                            <div className="flex flex-wrap gap-2">
                                                {skillItems.map((skill) => (
                                                    <span
                                                        key={skill}
                                                        className="inline-flex rounded-lg border border-[#E0E7FF] bg-[#EEF2FF] px-2.5 py-1 text-xs font-medium text-primery-blue-900"
                                                    >
                                                        {skill}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </>
                                ) : null}

                                {applicant.notes?.trim() ? (
                                    <>
                                        <Separator className="bg-[#E8E7EA]" />
                                        <div>
                                            <p className="mb-2 text-xs font-medium text-[#625E74]">
                                                ملاحظات المسار
                                            </p>
                                            <div
                                                className="quill-content max-h-48 overflow-y-auto rounded-xl border border-[#E5E7EB] bg-[#FAFAFA] p-3 text-sm leading-relaxed text-[#111827] shadow-inner [&_p]:my-1"
                                                // eslint-disable-next-line react/no-danger
                                                dangerouslySetInnerHTML={{ __html: applicant.notes }}
                                            />
                                        </div>
                                    </>
                                ) : null}
                            </div>
                        </>
                    ) : (
                        <div className="px-5 py-12 text-center text-sm text-[#9CA3AF] sm:px-6">
                            لا يوجد مرشح محدد
                        </div>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}
