import { Customer } from '@/types/customer.types';
import { Deal } from '../../types/configs.types';
import { Applicant } from '../../types/app.types';
import { Interview } from '../../types/interview.types';

export const formatCurrency = (value: number): string => {
    return `${value.toLocaleString('ar-EG')} ج.م`;
};

export const formatDateToArabic = (dateString: string): string => {
    const date = new Date(dateString);
    const year = date.getFullYear();
    const month = date.getMonth() + 1;
    const day = date.getDate();

    const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
    const convertToArabic = (num: number): string => {
        return num
            .toString()
            .split('')
            .map((digit) => arabicNumerals[parseInt(digit)])
            .join('');
    };

    return `${convertToArabic(year)}/${convertToArabic(month)}/${convertToArabic(day)}`;
};

/** `datetime-local` value → `Y-m-d H:i:s` for API, or undefined if empty/invalid. */
export function formatDatetimeLocalForApi(datetimeLocal: string): string | undefined {
    const raw = datetimeLocal?.trim();
    if (!raw) return undefined;
    const date = new Date(raw);
    if (Number.isNaN(date.getTime())) return undefined;
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const h = String(date.getHours()).padStart(2, '0');
    const min = String(date.getMinutes()).padStart(2, '0');
    return `${y}-${m}-${d} ${h}:${min}:00`;
}

/** HTML `date` + `time` inputs → same API format; both required or returns undefined. */
export function formatDateAndTimeForApi(dateStr: string, timeStr: string): string | undefined {
    const d = dateStr?.trim();
    const t = timeStr?.trim();
    if (!d || !t) return undefined;
    return formatDatetimeLocalForApi(`${d}T${t}`);
}

/** True when Quill/HTML note has no visible text (empty paragraphs only). */
export function isRichTextNotesEmpty(html: string): boolean {
    const text = html
        .replace(/<[^>]+>/g, ' ')
        .replace(/&nbsp;/gi, ' ')
        .replace(/\u200c/g, '')
        .trim();
    return text.length === 0;
}

export function formatDateTimeArEg(isoOrSql: string): string {
    const date = new Date(isoOrSql);
    if (Number.isNaN(date.getTime())) {
        return isoOrSql;
    }
    return new Intl.DateTimeFormat('ar-EG', {
        dateStyle: 'medium',
        timeStyle: 'short',
    }).format(date);
}

export const getInitials = (name: string): string => {
    if (!name) return '';
    return name
        .split(' ')
        .map((word) => word[0])
        .join('')
        .toLowerCase()
        .substring(0, 1);
};

/** Maps DB `pipeline_stage` to Kanban column `type` (see `constants.ts`). */
export function normalizePipelineStage(stage: string | null | undefined): string {
    const s = (stage || 'new').toLowerCase().trim();
    if (s === 'new') return 'in_progress';
    return s;
}

type DealExtras = {
    jobTitle?: string;
    experienceLabel?: string;
    tags?: string[];
    /** Resolved label for the applicant's pipeline stage (for Kanban card UI). */
    pipeline_stage?: string;
};

export function transformApplicantToDeal(applicant: Applicant): Deal & DealExtras {
    const rawSkills = applicant.skills ?? applicant.skills_text;
    const tags: string[] = Array.isArray(rawSkills)
        ? rawSkills.flatMap((s) =>
              String(s)
                  .split(/[\r\n,،]+|\s+/)
                  .map((x) => x.trim())
                  .filter(Boolean),
          )
        : typeof rawSkills === 'string'
          ? rawSkills
                .split(/[\r\n,،]+|\s+/)
                .map((s) => s.trim())
                .filter(Boolean)
          : [];

    const jobTitle =
        applicant.job?.title ?? applicant.job?.name ?? applicant.job_title ?? applicant.description ?? '';

    const parts = [applicant.level, applicant.work_type].filter(
        (x): x is string => typeof x === 'string' && x.trim().length > 0,
    );
    const experienceLabel = parts.join(' · ');

    const normalizedType = normalizePipelineStage(applicant.pipeline_stage);
    const pipelineStageRaw = applicant.pipeline_stage?.trim() ? applicant.pipeline_stage.trim() : '—';

    return {
        id: applicant.id.toString(),
        name: applicant.name,
        color: '',
        type: normalizedType,
        jobTitle,
        experienceLabel,
        tags: tags.slice(0, 6),
        pipeline_stage: pipelineStageRaw,
    };
}

/** يبني كائن مقابلة للعرض في نافذة التقييم من بيانات المرشح في الكنبان */
export function applicantToEvaluationInterview(applicant: Applicant): Interview {
    const jobTitle = applicant.job?.title ?? applicant.job?.name ?? applicant.job_title ?? '';
    return {
        id: applicant.id,
        career_applicant_id: applicant.id,
        created_at: applicant.created_at,
        updated_at: applicant.updated_at,
        applicant: {
            id: applicant.id,
            name: applicant.name,
            level: applicant.level ?? undefined,
            work_type: applicant.work_type ?? undefined,
            job: applicant.job?.id
                ? {
                      id: applicant.job.id,
                      title: applicant.job.title ?? applicant.job.name ?? null,
                  }
                : null,
        },
        name: applicant.name,
        description: jobTitle || undefined,
        experience_years: applicant.experience_years,
    };
}

export function transformCustomerToDeal(customer: Customer): Deal & DealExtras {
    return {
        id: customer.id.toString(),
        name: customer.full_name || '',
        color: '',
        type: (customer as Customer & { type?: string }).type || 'in_progress',
    };
}
