import { Card } from '@/components/ui/card';
import { DndContext, DragOverlay, closestCorners, DragStartEvent, DragEndEvent } from '@dnd-kit/core';
import { cn } from '@/lib/utils';
import DraggableCard from './DraggableCard';
import DroppableColumn from './DroppableColumn';
import { SalesStage } from '../../types/configs.types';
import { useRef, useState, useEffect } from 'react';
import LeftArrow from '@/components/icons/LeftArrow';
import RightArrow from '@/components/icons/RightArrow';


interface KanbanBoardProps {
    salesStages: SalesStage[];
    activeId: string | null;
    sensors: any;
    onDragStart: (event: DragStartEvent) => void;
    onDragEnd: (event: DragEndEvent) => void;
    onCardClick: (dealId: string) => void;
}

export default function KanbanBoard({
    salesStages,
    activeId,
    sensors,
    onDragStart,
    onDragEnd,
    onCardClick,
}: KanbanBoardProps) {
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const headersContainerRef = useRef<HTMLDivElement>(null);
    const [showLeftArrow, setShowLeftArrow] = useState(false);
    const [showRightArrow, setShowRightArrow] = useState(false);

    const checkScrollButtons = () => {
        if (scrollContainerRef.current) {
            const { scrollLeft, scrollWidth, clientWidth } = scrollContainerRef.current;
            const hasHorizontalScroll = scrollWidth > clientWidth;
            setShowLeftArrow(hasHorizontalScroll && scrollLeft > 10);
            setShowRightArrow(hasHorizontalScroll && scrollLeft < scrollWidth - clientWidth - 10);
        }
    };

    useEffect(() => {
        // Delay to ensure DOM is ready
        const timer = setTimeout(() => {
            checkScrollButtons();
        }, 100);

        const container = scrollContainerRef.current;
        const headersContainer = headersContainerRef.current;

        // Sync headers scroll with content scroll
        const syncHeadersScroll = () => {
            if (container && headersContainer) {
                headersContainer.scrollLeft = container.scrollLeft;
            }
        };

        if (container) {
            container.addEventListener('scroll', () => {
                checkScrollButtons();
                syncHeadersScroll();
            });
            window.addEventListener('resize', checkScrollButtons);
            return () => {
                clearTimeout(timer);
                container.removeEventListener('scroll', checkScrollButtons);
                window.removeEventListener('resize', checkScrollButtons);
            };
        }
    }, [salesStages]);

    const scrollLeft = () => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollBy({
                left: -350,
                behavior: 'smooth',
            });
        }
    };

    const scrollRight = () => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollBy({
                left: 350,
                behavior: 'smooth',
            });
        }
    };
    // console.log('salesStages', salesStages);

    return (
        <DndContext
            sensors={sensors}
            collisionDetection={closestCorners}
            onDragStart={onDragStart}
            onDragEnd={onDragEnd}
        >
            <div className="relative w-full h-full flex flex-col">
                {/* Fixed Headers Row */}
                <div
                    ref={headersContainerRef}
                    className="flex gap-4 pb-2 flex-shrink-0 overflow-x-hidden overflow-y-hidden kanban-headers"
                >
                    <style>{`
                        .kanban-headers {
                            scrollbar-width: none;
                            -ms-overflow-style: none;
                        }
                        .kanban-headers::-webkit-scrollbar {
                            display: none;
                        }
                    `}</style>
                    {salesStages.map((stage) => (
                        <div
                            key={`header-${stage.id}`}
                            className="flex-shrink-0 w-[300px]"
                        >
                            <div className={cn('rounded-lg p-4', stage.color, 'shadow-sm')}>
                                <div className="flex items-center justify-between">
                                    <h3 className="font-semibold text-gray-800 font-cairo">{stage.name}</h3>
                                    <span className="text-sm text-gray-600 font-cairo">{stage.count}</span>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Scrollable Container */}
                <div className="relative flex-1 min-h-0">
                    {/* Left Arrow */}
                    {/* {showLeftArrow && ( */}
                    <button
                        onClick={scrollLeft}
                        className="absolute left-[-30px] top-1/2 -translate-y-1/2 z-50 bg-white border-2 border-gray-300 rounded-full p-3 shadow-xl hover:bg-primery-blue-50 hover:border-primery-blue-400 transition-all duration-200 hover:scale-110"
                        aria-label="Scroll left"
                    >
                        <LeftArrow width="20" height="20" color="#6b7280" />
                    </button>
                    {/* )} */}

                    <div
                        ref={scrollContainerRef}
                        className="flex gap-4 overflow-x-hidden overflow-y-auto h-full pb-4 kanban-scroll"
                        style={{ height: 'calc(100vh - 320px)', minHeight: '650px' }}
                    >
                        <style>{`
                            .kanban-scroll {
                                scrollbar-width: thin;
                                scrollbar-color: #cbd5e1 transparent;
                            }
                            .kanban-scroll::-webkit-scrollbar {
                                width: 8px;
                            }
                            .kanban-scroll::-webkit-scrollbar-track {
                                background: transparent;
                            }
                            .kanban-scroll::-webkit-scrollbar-thumb {
                                background-color: #cbd5e1;
                                border-radius: 4px;
                            }
                            .kanban-scroll::-webkit-scrollbar-thumb:hover {
                                background-color: #94a3b8;
                            }
                        `}</style>
                        {salesStages.map((stage) => (
                            <DroppableColumn key={stage.id} stage={stage} activeId={activeId}>
                                {/* Deal Cards */}
                                <div className="space-y-4">
                                    {stage?.deals?.length === 0 ? (
                                        <div className="text-center py-8 text-gray-400 font-cairo text-sm min-h-[100px] rounded-lg border-2 border-dashed border-gray-300">
                                            لا توجد صفقات
                                        </div>
                                    ) : (
                                        stage?.deals?.map((deal) => (
                                            <DraggableCard
                                                key={deal.id}
                                                deal={deal}
                                                activeId={activeId}
                                                onCardClick={onCardClick}
                                            />
                                        ))
                                    )}
                                </div>
                            </DroppableColumn>
                        ))}
                    </div>

                    {/* Right Arrow */}
                    {showRightArrow && (
                        <button
                            onClick={scrollRight}
                            className="absolute right-[-22px] top-1/2 -translate-y-1/2 z-50 bg-white border-2 border-gray-300 rounded-full md:p-3 p-2 shadow-xl hover:bg-primery-blue-50 hover:border-primery-blue-400 transition-all duration-200 hover:scale-110"
                            aria-label="Scroll right"
                        >
                            <RightArrow width="20" height="20" color="#6b7280" />
                        </button>
                    )}
                </div>
            </div>
            <DragOverlay>
                {activeId ? (
                    <Card className="bg-white rounded-xl shadow-lg p-4 w-[280px] rotate-2">
                        <div className="space-y-3">
                            {(() => {
                                const deal = salesStages.flatMap((s) => s?.deals)?.find((d) => d?.id === activeId);
                                if (!deal) return null;
                                return (
                                    <>
                                        <h4 className="font-semibold text-gray-800 font-cairo text-base">
                                            {deal.name}
                                        </h4>
                                        {(deal as { jobTitle?: string }).jobTitle ? (
                                            <p className="text-sm text-gray-600 font-cairo">
                                                {(deal as { jobTitle?: string }).jobTitle}
                                            </p>
                                        ) : null}
                                        {'client' in deal && deal.client ? (
                                            <p className="text-sm text-gray-600 font-cairo">{String(deal.client)}</p>
                                        ) : null}
                                    </>
                                );
                            })()}
                        </div>
                    </Card>
                ) : null}
            </DragOverlay>
        </DndContext>
    );
}
